// 有限来源替身只代表已登记实际结果，测试不会为生产提供隐式全世界回退。
struct Results final:DynamicResultRead {
    std::vector<DynamicFactView> facts;
    const DeliveryFact* delivery(const StableId&)const override{return nullptr;}
    std::optional<DynamicFactView> fact(const StableId& id)const override{for(const auto& f:facts)if(f.id==id)return f;return {};}
    std::vector<StableId> fact_ids(Integer after,Integer through)const override{std::vector<StableId> ids;for(const auto& f:facts)if(f.tick>after&&f.tick<=through)ids.push_back(f.id);return ids;}
};
struct Organizations final:OrganizationRead {
    bool accepts_duty=true;std::optional<OrganizationMemberView> membership;
    bool organization_exists(const StableId&)const override{return true;}
    bool organization_active(const StableId&)const override{return true;}
    bool institutional_obligation_allowed(const StableId&,const StableId&,const StableId&,const StableId&,Integer,Integer)const override{return false;}
    bool actor_accepts_duty(const StableId&,const StableId&)const override{return accepts_duty;}
    std::optional<Integer> authority_epoch(const StableId&)const override{return {};}
    Outcome<AuthorityProof> authorize(const ActingAuthority&,const StableId&,const ScopeRef&,Integer)const override{return {false,{},common_failure("AuthorityUnavailable").error};}
    std::optional<OrganizationMemberView> member_view(const StableId& actor,const StableId& organization)const override{if(membership&&membership->actor_id==actor&&membership->organization_id==organization)return membership;return {};}
};
