// 共同检查点覆盖tick、钱包、行动、实例序号和全部RNG流，空闲复评不得改变其中任何字节。
CodecVisitor::Buffer idle_common_bytes(CommonState state){CodecVisitor::Buffer bytes;CodecVisitor writer(bytes);assert(visit_common_checkpoint(writer,state).ok&&writer.finish().ok);return bytes;}
