        seed.common.roles.insert("clerk",{"a",true,{}});seed.common.roles.insert("employer",{"b",true,{}});seed.common.rng.insert("world",{17,23,{}});seed.common.rng.insert("event",{31,47,{}});
        seed.travel=std::make_shared<TravelState>();seed.military=std::make_shared<MilitaryState>();seed.interaction=std::make_shared<InteractionState>();seed.social=std::make_shared<SocialState>();seed.estate=std::make_shared<EstateState>();seed.tasks=std::make_shared<TaskState>();seed.family=std::make_shared<FamilyState>();seed.personal=std::make_shared<PersonalState>();seed.growth=std::make_shared<GrowthState>();
