// 空闲复评只持久化计划；真正的玩家等待、提供人等待和工作仍占用原行动及交谈入口。
void check_idle_contact(){
    IdleContactFixture f;auto& w=*f.world;const auto before=idle_common_bytes(w.common.state());const auto unreviewed=director_bytes(w.director);
    auto idle=f.propose("a");assert(idle.ok&&idle.value.size()==1);const auto& proposal=idle.value.front();assert(!proposal.command&&proposal.transition->phase==PlanPhase::waiting&&proposal.transition->wait_reason=="NoImmediateAction"&&proposal.transition->template_id=="await_adjustment"&&proposal.transition->goal_ref.empty()&&proposal.transition->next_step_index==0);
    assert(idle_common_bytes(w.common.state())==before&&director_bytes(w.director)==unreviewed);
    assert(apply_director_proposal(w,proposal,0).ok);assert(idle_common_bytes(w.common.state())==before);
    const auto* plan=w.director.plans.find("a");const auto* schedule=w.director.schedules.find("a");assert(plan&&schedule&&plan->phase==PlanPhase::waiting&&plan->retry_reason=="NoImmediateAction"&&!plan->current_action_id&&plan->next_review_tick==2&&schedule->next_tick==2&&schedule->last_outcome=="NoImmediateAction"&&schedule->decision_seq==1&&w.director.fairness_cursor==1);
    CommandPayload talk{"talk",InteractionCommand{Talk{"clerk"}}};assert(prepare_command(w,"player",talk).ok);
    auto due=director_due_subjects(w.common,w.director,*f.policies,w.tasks,0);assert(due.ok&&due.value==std::vector<StableId>{"b"});
    const auto reviewed=director_bytes(w.director);assert(!apply_director_proposal(w,proposal,0).ok&&director_bytes(w.director)==reviewed&&idle_common_bytes(w.common.state())==before);
    assert(run_dynamic_decisions(w,0).ok&&w.director.fairness_cursor==2&&idle_common_bytes(w.common.state())==before);assert(run_dynamic_decisions(w,0).ok&&w.director.fairness_cursor==2);
    w.common.state().identity.tick=1;due=director_due_subjects(w.common,w.director,*f.policies,w.tasks,1);assert(due.ok&&due.value.empty());
    w.common.state().identity.tick=2;auto at_review=idle_common_bytes(w.common.state());assert(run_dynamic_decisions(w,2).ok&&w.director.schedules.find("a")->next_tick==4&&w.director.schedules.find("a")->decision_seq==2&&w.director.fairness_cursor==3&&idle_common_bytes(w.common.state())==at_review);
    w.common.state().identity.tick=3;at_review=idle_common_bytes(w.common.state());assert(run_dynamic_decisions(w,3).ok&&w.director.schedules.find("b")->next_tick==5&&w.director.schedules.find("b")->decision_seq==2&&w.director.fairness_cursor==4&&idle_common_bytes(w.common.state())==at_review);assert(prepare_command(w,"player",talk).ok&&validate_director(w.common,w.director,*f.policies).ok);
    const auto saved=director_bytes(w.director);DirectorState restored;CodecVisitor reader(saved);assert(visit_director_checkpoint(reader,restored).ok&&reader.finish().ok&&director_bytes(restored)==saved);auto cold=decode_director_seed(encode_director_state(w.director));assert(cold.ok&&director_bytes(cold.value)==saved);
    for(const StableId actor:{"player","a"}){
        IdleContactFixture occupied;auto& current=*occupied.world;CommandPayload wait{"wait",WaitCommand{}};auto quote=prepare_command(current,actor,wait);assert(quote.ok);auto result=apply_command(current,actor,*quote.value->operation);assert(result.ok);const auto* started=std::get_if<ActionStarted>(&result.value.data);assert(started);const auto* action=current.common.action(started->action_id);assert(action&&action->kind=="wait"&&action->remaining_ticks==1&&current.common.actor(actor)->action_id==started->action_id&&current.common.tick()==0);
        auto busy=prepare_command(current,"player",talk);assert(!busy.ok&&busy.error.original.code=="ActorBusy");auto selected=director_due_subjects(current.common,current.director,*occupied.policies,current.tasks,0);assert(selected.ok&&selected.value==std::vector<StableId>{actor=="a"?"b":"a"});
    }
    IdleContactFixture working;auto& busy_world=*working.world;GrowthCommand work;work.kind="service";work.activity="work";work.context=InteractionContext{"market","b","employer",{},{},{},{}};auto quote=prepare_command(busy_world,"a",CommandPayload{"service",work});assert(quote.ok);auto applied=apply_command(busy_world,"a",*quote.value->operation);assert(applied.ok);const auto* action=std::get_if<ActionStarted>(&applied.value.data);assert(action&&busy_world.common.action(action->action_id)->kind=="service"&&busy_world.common.actor("a")->action_id==action->action_id&&busy_world.common.actor("b")->action_id==action->action_id);
    auto selected=director_due_subjects(busy_world.common,busy_world.director,*working.policies,busy_world.tasks,0);assert(selected.ok&&selected.value.empty());auto busy=prepare_command(busy_world,"player",talk);assert(!busy.ok&&busy.error.original.code=="ActorBusy");const auto occupied=idle_common_bytes(busy_world.common.state());assert(run_dynamic_decisions(busy_world,0).ok&&idle_common_bytes(busy_world.common.state())==occupied&&busy_world.director.fairness_cursor==0);
}
// 队列晚于合法当地观察送达时保留最早知情；另一条消息的到期不能倒改该来源。
void check_local_observation_before_delivery(){
    auto common=fixture();common.state().actors.find("b")->location=SettlementLocation{"town","market"};SocialState social;assert(initialize_dynamic_social(social).ok);Results results;DynamicFactView fact;fact.id="supply:1";fact.kind="supply";fact.rule_version="1";fact.publicly_visible=true;fact.participants={{{SubjectKind::actor,"a"},"observer"}};fact.supply=SupplyObservation{"shop.grain","city","market","shop.inventory","grain",fact.id,10,7,1};results.facts.push_back(fact);assert(collect_dynamic_reports(common,social,results,0).ok);
    const StableId report_id="report:supply:1";auto queued=queue_dynamic_report(common,social,report_id,{SubjectKind::actor,"a"},{SubjectKind::actor,"b"},"official_supply_report",0,1);assert(queued.ok);assert(observe_dynamic_report(common,social,report_id,{SubjectKind::actor,"b"},0).ok);assert(validate_dynamic_social(common,social,&results).ok);auto* first=social.dynamic->known_reports.find("0:b")->find(report_id);assert(first&&first->learned_tick==0&&!first->source_message_id&&first->source_subject.id=="b");
    common.state().identity.tick=1;common.state().actors.find("b")->location=SettlementLocation{"other","far"};DynamicStepInput due{0,1,{}, {queued.value},{}};assert(deliver_dynamic_reports(common,social,due).ok);auto valid=validate_dynamic_social(common,social,&results);if(!valid.ok)std::cerr<<"local-observation delivery: "<<valid.error.original.code<<"\n";assert(valid.ok);auto* preserved=social.dynamic->known_reports.find("0:b")->find(report_id);assert(preserved->learned_tick==0&&!preserved->source_message_id&&preserved->source_subject.kind==SubjectKind::actor&&preserved->source_subject.id=="b");assert(social.dynamic->pending_messages.find(queued.value)->status==MessageStatus::delivered);auto delivered=social_bytes(*social.dynamic);assert(deliver_dynamic_reports(common,social,due).ok&&delivered==social_bytes(*social.dynamic));
    auto forged=social;auto* forged_known=forged.dynamic->known_reports.find("0:b")->find(report_id);forged_known->source_message_id=queued.value;forged_known->source_subject={SubjectKind::actor,"a"};auto invalid=validate_dynamic_social(common,forged,&results);assert(!invalid.ok&&invalid.error.original.code=="InvalidKnownReportProvenance");auto future=social;future.dynamic->pending_messages.find(queued.value)->due_tick=2;invalid=validate_dynamic_social(common,future,&results);assert(!invalid.ok&&invalid.error.original.code=="InvalidDeliveredMessage");auto impossible=social;impossible.dynamic->known_reports.find("0:b")->find(report_id)->learned_tick=-1;assert(!validate_dynamic_social(common,impossible,&results).ok);
    auto forwarded=queue_dynamic_report(common,social,report_id,{SubjectKind::actor,"b"},{SubjectKind::actor,"c"},"courier",1,2);assert(forwarded.ok);auto before=social_bytes(*social.dynamic);assert(!deliver_dynamic_reports(common,social,{0,1,{}, {forwarded.value},{}}).ok&&before==social_bytes(*social.dynamic));assert(!social.dynamic->known_reports.find("0:c"));common.state().identity.tick=2;assert(deliver_dynamic_reports(common,social,{1,2,{}, {forwarded.value},{}}).ok);assert(validate_dynamic_social(common,social,&results).ok);auto* received=social.dynamic->known_reports.find("0:c")->find(report_id);assert(received->learned_tick==2&&received->source_message_id==std::optional<StableId>(forwarded.value));
}
